def run(*, uniprot_id: str, species: str = None, top_n: int = 10):
    """
    Search Reactome for pathways linked to a UniProt identifier.

    Parameters
    ----------
    uniprot_id : str
        UniProt accession (e.g., "P04637").
    species : str, optional
        Species filter (taxonomy ID or name, e.g., "9606").
    top_n : int, optional
        Maximum number of pathways to return (default 10).

    Returns
    -------
    dict
        {"pathways": [{"stId": "...", "displayName": "..."}, ...]}

    Raises
    ------
    LookupError
        If no pathways are found for the given identifier/species.
    """
    base_url = "https://reactome.org/ContentService"
    endpoint = f"/data/mapping/UniProt/{uniprot_id}/pathways"
